
CREATE TABLE resources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),module_id uuid NOT NULL,uploaded_by uuid NOT NULL REFERENCES users(id),type text NOT NULL CHECK(type IN ('LECTURE_NOTE','HANDWRITTEN_NOTE','PAST_PAPER','TUTORIAL','ASSIGNMENT','OTHER')),title text NOT NULL,description text NOT NULL DEFAULT '',academic_year text,exam_type text,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','ARCHIVED')),published_at timestamptz,current_version_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(batch_id,id),FOREIGN KEY(batch_id,module_id) REFERENCES modules(batch_id,id));
CREATE TABLE resource_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL,resource_id uuid NOT NULL,version_number int NOT NULL CHECK(version_number>0),storage_key text NOT NULL UNIQUE,file_name text NOT NULL,mime_type text NOT NULL CHECK(mime_type='application/pdf'),size_bytes bigint NOT NULL CHECK(size_bytes>0),original_size_bytes bigint NOT NULL CHECK(original_size_bytes>0),compression_profile text NOT NULL DEFAULT 'NONE' CHECK(compression_profile IN ('NONE','LOW_SIZE','BALANCED','HIGH_QUALITY')),page_count int CHECK(page_count>0),uploaded_by uuid NOT NULL REFERENCES users(id),change_note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(resource_id,version_number),UNIQUE(batch_id,resource_id,id),FOREIGN KEY(batch_id,resource_id) REFERENCES resources(batch_id,id));
ALTER TABLE resources ADD CONSTRAINT resource_current_version FOREIGN KEY(batch_id,id,current_version_id) REFERENCES resource_versions(batch_id,resource_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX resources_list ON resources(batch_id,module_id,status,published_at DESC,id DESC);
CREATE TABLE bookmarks(user_id uuid NOT NULL REFERENCES users(id),batch_id uuid NOT NULL,resource_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,resource_id),FOREIGN KEY(batch_id,resource_id) REFERENCES resources(batch_id,id));
